from pathlib import Path

class ProjectPath(Path):
    def __init__(self, *args, base=None):
        super().__init__(*args)
        self.base = base if base is not None else Path(*args)

    def with_segments(self, *segments):
        return type(self)(*segments, base=self.base)   # keep the context

    def rel(self):
        return self.relative_to(self.base)

    def is_test(self):
        return self.name.startswith("test_") and self.suffix == ".py"

Path("proj/tests").mkdir(parents=True)
Path("proj/tests/test_api.py").touch()
root = ProjectPath("proj")
f = next((root / "tests").iterdir())
print(type(f).__name__, f.rel(), f.is_test())   # ProjectPath tests/test_api.py True
print(type(f.parent).__name__, f.parent.base)   # ProjectPath proj

import os
import timeit
from pathlib import Path

d = Path("many")
d.mkdir()
for i in range(2000):
    (d / f"f{i}.txt").touch()

def with_pathlib():
    return sum(p.stat().st_size for p in d.iterdir() if p.is_file())

def with_scandir():
    with os.scandir(d) as it:
        return sum(e.stat().st_size for e in it if e.is_file())

print(with_pathlib() == with_scandir())   # True
t1 = timeit.timeit(with_pathlib, number=5)
t2 = timeit.timeit(with_scandir, number=5)
print(t2 < t1)                            # True
